#include "finance/FinanceSecurityManager.hpp"
namespace Pine::Finance {std::uint64_t FinanceSecurityManager::timeout()const{if(settings_.autoLock=="Immediately")return 0;if(settings_.autoLock=="1 minute")return 60000;if(settings_.autoLock=="5 minutes")return 300000;if(settings_.autoLock=="Never")return UINT64_MAX;return 300000;}bool FinanceSecurityManager::unlock(const std::string&pin,std::uint64_t now){if(!settings_.requireAuthentication){locked_=false;return true;}if(service_.authenticate(pin)){locked_=false;backgroundAt_=now;background_=false;return true;}return false;}void FinanceSecurityManager::onOpen(std::uint64_t now){if(settings_.requireAuthentication&&background_&&now-backgroundAt_>=timeout())locked_=true;background_=false;}void FinanceSecurityManager::onBackground(std::uint64_t now){backgroundAt_=now;background_=true;if(timeout()==0)locked_=true;}void FinanceSecurityManager::update(std::uint64_t now){if(settings_.requireAuthentication&&background_&&now-backgroundAt_>=timeout())locked_=true;}}
